    current_idx = {}
    for idx, row in dim[dim['is_current'] == 1].iterrows():
        current_idx[row['customer_id']] = idx

    def seg_equal(a, b):
        a_na = pd.isna(a)
        b_na = pd.isna(b)
        if a_na and b_na:
            return True
        if a_na != b_na:
            return False
